659	def validate_survey(obj):
660	    """Validate a decoded survey payload.
661	
662	    Returns (clean_survey, None) on success or (None, error_message) on failure.
663	    Strings are stored trimmed of surrounding whitespace; description keeps its
664	    raw value so Chinese, quotes and newlines are preserved.
665	    """
666	    if not isinstance(obj, dict):
667	        return None, "请求体必须是 JSON 对象"
668	    if "title" not in obj:
669	        return None, "缺少字段 title"
670	    title = obj["title"]
671	    if not isinstance(title, str):
672	        return None, "title 必须是字符串"
673	    title = title.strip()
674	    if not title:
675	        return None, "title 不能为空（或全为空白字符）"
676	
677	    description = obj.get("description", "")
678	    if not isinstance(description, str):
679	        return None, "description 必须是字符串"
680	
681	    if "questions" not in obj:
682	        return None, "缺少字段 questions"
683	    raw_questions = obj["questions"]
684	    if not isinstance(raw_questions, list):
685	        return None, "questions 必须是数组"
686	    if len(raw_questions) == 0:
687	        return None, "questions 至少需要一道题"
688	
689	    questions = []
690	    for index, raw_question in enumerate(raw_questions, start=1):
691	        location = f"第 {index} 题"
692	        if not isinstance(raw_question, dict):
693	            return None, f"{location}（questions[{index - 1}]）必须是对象"
694	
695	        if "type" not in raw_question:
696	            return None, f"{location}：缺少字段 type"
697	        question_type = raw_question["type"]
698	        if not isinstance(question_type, str):
699	            return None, f"{location}：type 必须是字符串"
700	        if question_type not in QUESTION_TYPES:
701	            shown = json.dumps(question_type, ensure_ascii=False)
702	            return None, f"{location}：不支持的题型 {shown}（仅支持 text 或 single_choice）"
703	
704	        if "title" not in raw_question:
705	            return None, f"{location}：缺少字段 title"
706	        question_title = raw_question["title"]
707	        if not isinstance(question_title, str):
708	            return None, f"{location}：title 必须是字符串"
709	        question_title = question_title.strip()
710	        if not question_title:
711	            return None, f"{location}：题目标题不能为空（或全为空白字符）"
712	
713	        required = raw_question.get("required", False)
714	        if not isinstance(required, bool):
715	            return None, f"{location}：required 必须是布尔值"
716	
717	        raw_options = raw_question.get("options", [])
718	        if not isinstance(raw_options, list):
719	            return None, f"{location}：options 必须是数组"
720	
721	        options = []
722	        if question_type == "text":
723	            if len(raw_options) > 0:
724	                return None, f"{location}：文本题不能包含选项（options 必须省略或为空数组）"
725	        else:
726	            if len(raw_options) < 2:
727	                return None, f"{location}：单选题至少需要两个选项"
728	            seen = set()
729	            for option_index, raw_option in enumerate(raw_options, start=1):
730	                if not isinstance(raw_option, str):
731	                    return None, f"{location}：第 {option_index} 个选项必须是字符串"
732	                option = raw_option.strip()
733	                if not option:
734	                    return None, f"{location}：第 {option_index} 个选项不能为空（或全为空白字符）"
735	                if option in seen:
736	                    shown = json.dumps(option, ensure_ascii=False)
737	                    return None, f"{location}：选项 {shown} 重复（同一题内选项不得重复）"
738	                seen.add(option)
739	                options.append(option)
740	
741	        questions.append({
742	            "type": question_type,
743	            "title": question_title,
744	            "required": required,
745	            "options": options,
746	        })
747	
748	    return {
749	        "title": title,
750	        "description": description,
751	        "questions": questions,
752	    }, None
753	
