881	    class Handler(BaseHTTPRequestHandler):
882	        def respond(self, status, value, *, html=False, allow=None):
883	            payload = value.encode("utf8") if html else json.dumps(value, ensure_ascii=False).encode("utf8")
884	            self.send_response(status)
885	            self.send_header("Content-Type", "text/html; charset=utf-8" if html else "application/json; charset=utf-8")
886	            self.send_header("Content-Length", str(len(payload)))
887	            if status == 405 and allow is not None:
888	                self.send_header("Allow", ", ".join(allow))
889	            self.end_headers()
890	            self.wfile.write(payload)
891	
892	        def list_surveys(self):
893	            with db_lock:
894	                records = [
895	                    {"id": row[0], "title": row[1]}
896	                    for row in database.execute("SELECT id, title FROM surveys ORDER BY id")
897	                ]
898	            self.respond(200, {RESOURCE: records})
899	
900	        def read_payload(self):
901	            """Read and decode a JSON request body.
902	
903	            Returns (payload, None) or (None, error_message).
904	            """
905	            try:
906	                length = int(self.headers.get("Content-Length") or 0)
907	            except ValueError:
908	                length = -1
909	            if length < 0:
910	                return None, "Content-Length 无效"
911	            if length > MAX_BODY_BYTES:
912	                return None, "请求体过大"
913	            body = self.rfile.read(length) if length else b""
914	            try:
915	                return json.loads(body.decode("utf8")), None
916	            except (UnicodeDecodeError, json.JSONDecodeError) as error:
917	                return None, f"请求体不是合法 JSON：{error}"
918	
