# 新建表单状态快照：题号/选项编号标签、原始输入值、错误标记与顶部提示全部取自
# 用户可见的 DOM。
SNAPSHOT_JS = r"""
(() => {
  const banner = document.getElementById('form-banner');
  const heading = document.querySelector('#draft-form h2');
  return {
    hash: location.hash,
    formHeading: heading ? heading.textContent : null,
