class ChromePage:
    def __init__(self, ws, target_id, session_id):
        self.ws = ws
        self.target_id = target_id
        self.session = session_id
        self.held_posts = []
        self._held_lock = threading.Lock()
        self._pumping = False

    def prepare(self):
